package com.eventticketing.notification;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.test.context.*;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
@SpringBootTest(properties={"app.messaging.enabled=false","management.health.mail.enabled=false","spring.kafka.admin.auto-create=false","app.mail.poll-millis=3600000"}) @Testcontainers
class NotificationIntegrationTest {
 @Container static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine").withInitScript("init.sql");
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);}
 @Autowired OrderNotification notifications;@Autowired MailWorker worker;@Autowired JdbcTemplate db;@Autowired ObjectMapper json;
 @MockitoBean IdentityContact identity;@MockitoBean JavaMailSender mail;
 String body(UUID message,UUID order,String status)throws Exception{return json.writeValueAsString(Map.of("eventId",message,"eventVersion",1,"payload",Map.of("id",order,"customerId",UUID.randomUUID(),"eventName","Synthetic event","totalVnd",100000,"status",status)));}
 @Test void confirmationHasOneDurableObligationAcrossDuplicateFacts()throws Exception{UUID id=UUID.randomUUID(),message=UUID.randomUUID();String body=body(message,id,"CONFIRMED");notifications.accept(body);notifications.accept(body);notifications.accept(body(UUID.randomUUID(),id,"CONFIRMED"));assertThat(db.queryForObject("select count(*) from notification.email_deliveries where order_id=?",Integer.class,id)).isEqualTo(1);}
 @Test void pendingOrPoisonMessageDoesNotCreateEmail()throws Exception{UUID id=UUID.randomUUID();assertThatThrownBy(()->notifications.accept(body(UUID.randomUUID(),id,"PENDING_PAYMENT"))).hasMessageContaining("confirmed");assertThat(db.queryForObject("select count(*) from notification.email_deliveries where order_id=?",Integer.class,id)).isZero();}
 @Test void smtpFailureKeepsObligationForRetryWithoutOrderMutation()throws Exception{db.update("update notification.email_deliveries set delivered_at=now()");UUID id=UUID.randomUUID();notifications.accept(body(UUID.randomUUID(),id,"CONFIRMED"));when(identity.read(any())).thenAnswer(a->new IdentityContact.Contact(a.getArgument(0),"fixture@example.test","Fixture"));doThrow(new IllegalStateException("SMTP unavailable")).when(mail).send(any(SimpleMailMessage.class));worker.deliver();assertThat(db.queryForObject("select delivered_at from notification.email_deliveries where order_id=?",java.sql.Timestamp.class,id)).isNull();db.update("update notification.email_deliveries set available_at=now()-interval '1 second' where order_id=?",id);doNothing().when(mail).send(any(SimpleMailMessage.class));worker.deliver();assertThat(db.queryForObject("select delivered_at from notification.email_deliveries where order_id=?",java.sql.Timestamp.class,id)).isNotNull();var messages=org.mockito.ArgumentCaptor.forClass(SimpleMailMessage.class);verify(mail,times(2)).send(messages.capture());assertThat(messages.getValue().getText()).contains("Đơn hàng của bạn đã được xác nhận",id.toString(),"/account/orders/").doesNotContain("mô phỏng","không thu tiền thật");}
 @Autowired TicketNotification ticketNotifications;@Autowired TicketMailWorker ticketWorker;
 @Test void ticketEmailDeduplicatesRetriesAndOnlyContainsAuthenticatedLink()throws Exception{db.update("update notification.ticket_deliveries set delivered_at=now()");UUID order=UUID.randomUUID(),customer=UUID.randomUUID();String body=json.writeValueAsString(Map.of("eventId",UUID.randomUUID(),"producer","ticket-admission","eventType","ticket.order.ready.v1","eventVersion",1,"payload",Map.of("orderId",order,"customerId",customer,"eventName","Ticket fixture")));ticketNotifications.accept(body);ticketNotifications.accept(body);assertThat(db.queryForObject("select count(*) from notification.ticket_deliveries where order_id=?",Integer.class,order)).isEqualTo(1);when(identity.read(customer)).thenReturn(new IdentityContact.Contact(customer,"fixture@example.test","Fixture"));doThrow(new IllegalStateException("SMTP down")).when(mail).send(any(SimpleMailMessage.class));ticketWorker.deliver();assertThat(db.queryForObject("select delivered_at from notification.ticket_deliveries where order_id=?",java.sql.Timestamp.class,order)).isNull();db.update("update notification.ticket_deliveries set available_at=now()-interval '1 second' where order_id=?",order);doNothing().when(mail).send(any(SimpleMailMessage.class));ticketWorker.deliver();var captured=org.mockito.ArgumentCaptor.forClass(SimpleMailMessage.class);verify(mail,times(2)).send(captured.capture());assertThat(captured.getValue().getText()).contains("Đăng nhập","/account/orders/"+order).doesNotContain("ETP1.");}

 @MockitoBean OperationsSources sources;@Autowired OperationsInbox operations;@Autowired OperationsMailWorker operationsWorker;
 @Test void reminderHasOneObligationPerRecipientAndRechecksCurrentEligibility()throws Exception{
  db.update("update notification.operations_deliveries set delivered_at=now()");UUID event=UUID.randomUUID(),user=UUID.randomUUID();var p=json.createObjectNode().put("kind","REMINDER").put("eventId",event.toString()).put("userId",user.toString()).put("name","Reminder fixture").put("startAt","2030-01-01T12:00:00Z");operations.reminder(p);operations.reminder(p);
  when(sources.reminderEligible(any())).thenReturn(false);operationsWorker.deliver();verifyNoInteractions(mail);assertThat(db.queryForObject("select count(*) from notification.operations_deliveries where obligation_key=?",Integer.class,"reminder:"+event)).isEqualTo(1);
  when(sources.reminderEligible(any())).thenReturn(true);when(identity.read(user)).thenReturn(new IdentityContact.Contact(user,"reminder@example.test","Fixture","en"));db.update("update notification.operations_deliveries set available_at=now()-interval '1 second' where user_id=?",user);operationsWorker.deliver();operations.reminder(p);operationsWorker.deliver();var captured=org.mockito.ArgumentCaptor.forClass(SimpleMailMessage.class);verify(mail,times(1)).send(captured.capture());assertThat(captured.getValue().getSubject()).contains("coming up");assertThat(captured.getValue().getText()).contains("/account/orders").doesNotContain("ETP1.");
 }
 @Test void operationMailRetriesSmtpAndUnknownLocaleFallsBackToVietnamese()throws Exception{
  db.update("update notification.operations_deliveries set delivered_at=now()");UUID user=UUID.randomUUID();var p=json.createObjectNode().put("id",UUID.randomUUID().toString()).put("kind","APPLICATION_APPROVED").put("userId",user.toString()).put("name","Local organizer");operations.accept("organization",p);operations.accept("organization",p);when(identity.read(user)).thenReturn(new IdentityContact.Contact(user,"fixture@example.test","Fixture","other"));doThrow(new IllegalStateException("SMTP unavailable")).when(mail).send(any(SimpleMailMessage.class));operationsWorker.deliver();assertThat(db.queryForObject("select delivered_at from notification.operations_deliveries where user_id=?",java.sql.Timestamp.class,user)).isNull();db.update("update notification.operations_deliveries set available_at=now()-interval '1 second' where user_id=?",user);doNothing().when(mail).send(any(SimpleMailMessage.class));operationsWorker.deliver();var captured=org.mockito.ArgumentCaptor.forClass(SimpleMailMessage.class);verify(mail,times(2)).send(captured.capture());assertThat(captured.getValue().getSubject()).contains("đã được duyệt");
 }
}
